1	/** Number of swatches visible per pagination page. PM-confirmed max colour count is 7. */
2	export const SWATCHES_PER_PAGE = 4;
3

1	/**
2	 * Maps a Commerce API product onto the props the PDP's static-information components take.
3	 *
4	 * Extracted from the page so the mapping is unit-testable on its own. Nothing else on the PDP
5	 * ties an external field name to a rendered prop, and a mis-keyed field here does not fail
6	 * loudly: it falls through to `undefined`, the component returns `null`, and the page renders
7	 * a plausible-looking product with one line quietly missing. Neither a Storybook `play`
8	 * (which supplies its own props) nor an axe run can see that.
9	 */
10	
11	/*
12	 * The Commerce SDK's `Product` type does not carry Zimmermann's `c_*` custom attributes, and
13	 * `@salesforce/retail-react-app` ships no types at all. This is the narrow shape this mapping
14	 * actually reads — everything optional, because every one of these fields can be absent on a
15	 * real catalogue product.
16	 */
17	/**
18	 * Shape of `c_tabDescription`/`c_tabDetails` — a rich-text attribute authored with both a
19	 * rendered `markup` (HTML, same shape as `longDescription`) and its plain-text `source`. Only
20	 * `markup` is read below, matching how every other rich-text field on this page is consumed
21	 * (through `app/utils/richText`'s HTML parser, not the plain-text form).
22	 */
23	export type SfccRichTextAttribute = {
24	  markup?: string;
25	  source?: string;
26	};
27	
28	export type PdpSourceProduct = {
29	  id?: string;
30	  name?: string;
31	  longDescription?: string;
32	  /** Master product reference. Present on a variant; absent on a standard product. */
33	  master?: { masterId?: string };
34	  /** Zimmermann custom attribute holding the model's measurements and worn size. */
35	  c_modelFit?: string;
36	  /** Zimmermann custom attribute holding the product's care instructions, authored in Business
37	   *  Manager with the same markup shape as `longDescription` (see `app/utils/richText`). */
38	  c_careInstructions?: string;
39	  /** Colour code (e.g. "GVSCP") — not a display name. */
40	  c_color?: string;
41	  c_colourId?: string;
42	  /** EU Environmental Qualities content — SFCC-266's data source (MuleSoft/AP21), not this
43	   *  page's own concern yet; mapped here so that tab has it ready when it's built. */
44	  c_environmentalNotes?: string;
45	  c_fabricComposition?: string;
46	  /** Customs/tariff Harmonized System code — not a PDP display field. */
47	  c_hsCode?: string;
48	  /** SFCC-102's Size & Fit content, if/when that tab moves off Contentful onto this attribute —
49	   *  see the plan doc's note that Size & Fit was assumed Contentful-managed; not wired into
50	   *  DetailsAndCareContent or the Size & Fit tab yet, pending that confirmation. */
51	  c_sizeFit?: string;
52	  c_styleId?: string;
53	  c_styleNumber?: string;
54	  c_stylingNotes?: string;
55	  c_tabDescription?: SfccRichTextAttribute;
56	  c_tabDetails?: SfccRichTextAttribute;
57	};
58	
59	/** The subset of `getPriceData`'s result this mapping needs. */
60	export type PdpSourcePrice = {
61	  currentPrice?: number;
62	  /** True when the variant's selling price is below its list (RRP) price — PRC-09. */
63	  isOnSale?: boolean;
64	  /** The original RRP. Present when `isOnSale` is true. */
65	  listPrice?: number;
66	  /**
67	   * True when `currentPrice` is the minimum across a set of variants rather than a single
68	   * definite price — e.g. a colour-only selection where sizes have different sale prices.
69	   * When true, Was/Now is suppressed: `currentPrice` is not a settled figure and showing a
70	   * definite Was/Now would misrepresent the product's pricing.
71	   */
72	  isRange?: boolean;
73	};
74	
75	/** Formats a bare amount for the storefront. Injected so this module stays free of react-intl. */
76	export type FormatPrice = (amount: number, currency: string) => string;
77	
78	export type PdpProductInfo = {
79	  name: string;
80	  /** Active selling price (the "Now" price when on sale). */
81	  price: string;
82	  /** Original RRP. Present only when the product is on sale (PRC-09). */
83	  wasPrice?: string;
84	  description?: string;
85	  modelInfo?: string;
86	  careInstructions?: string;
87	  styleCode?: string;
88	  colour?: string;
89	  colourId?: string;
90	  environmentalNotes?: string;
91	  fabricComposition?: string;
92	  hsCode?: string;
93	  sizeFit?: string;
94	  styleId?: string;
95	  styleNumber?: string;
96	  stylingNotes?: string;
97	  tabDescription?: string;
98	  tabDetails?: string;
99	};
100	
101	/**
102	 * @param product - The resolved product (variant when one is selected, master otherwise).
103	 * @param priceData - `getPriceData(...)`'s result, as ProductView computes it.
104	 * @param currency - The storefront's active currency code.
105	 * @param formatPrice - Currency formatter, normally `intl.formatNumber`.
106	 * @returns Props for the static-information components, or `null` while the product loads.
107	 */
108	/** One item in the `c_relatedSwatches` array resolved by the SCAPI hook (SFCC-708). */
109	export type RelatedSwatch = {
110	  masterProductID: string;
111	  colourValue: string;
112	  displayName: string;
113	  swatchImageURL: string;
114	};
115	
116	export const selectPdpProductInfo = (
117	  product: PdpSourceProduct | undefined | null,
118	  priceData: PdpSourcePrice | undefined | null,
119	  currency: string,
120	  formatPrice: FormatPrice,
121	): PdpProductInfo | null => {
122	  if (!product?.name) return null;
123	
124	  return {
125	    name: product.name,
126	    price: typeof priceData?.currentPrice === 'number' ? formatPrice(priceData.currentPrice, currency) : '',
127	    // PRC-09: expose the original RRP as wasPrice only when the item is genuinely on sale,
128	    // the price is a settled definite figure (not a range minimum), and the list price is a
129	    // real number. When `isRange` is true, `currentPrice` is the cheapest across a set of
130	    // variants — showing a definite Was/Now would misrepresent the price for other variants.
131	    // The Was/Now atoms branch on wasPrice's presence; when absent ZimmProductPrice renders
132	    // the standard single-price treatment.
133	    wasPrice:
134	      priceData?.isOnSale &&
135	      !priceData.isRange &&
136	      typeof priceData.currentPrice === 'number' &&
137	      typeof priceData.listPrice === 'number'
138	        ? formatPrice(priceData.listPrice, currency)
139	        : undefined,
140	    description: product.longDescription,
141	    modelInfo: product.c_modelFit,
142	    careInstructions: product.c_careInstructions,
143	    // The style code shoppers see is the *master* style number. `product.id` is the variant
144	    // SKU once a size is selected, so reading it would silently show a different value after
145	    // the first swatch click. Standard products have no master, and there `id` is correct.
146	    // Unchanged by the c_styleNumber addition below: Tim hasn't confirmed this should switch to
147	    // that attribute, only that c_styleNumber should be mapped and available.
148	    styleCode: product.master?.masterId ?? product.id,
149	    colour: product.c_color,
150	    colourId: product.c_colourId,
151	    environmentalNotes: product.c_environmentalNotes,
152	    fabricComposition: product.c_fabricComposition,
153	    hsCode: product.c_hsCode,
154	    sizeFit: product.c_sizeFit,
155	    styleId: product.c_styleId,
156	    styleNumber: product.c_styleNumber,
157	    stylingNotes: product.c_stylingNotes,
158	    tabDescription: product.c_tabDescription?.markup,
159	    tabDetails: product.c_tabDetails?.markup,
160	  };
161	};
162	
163	/**
164	 * Maps SCAPI `c_relatedSwatches` items onto ZimmColourSwatchGroup-compatible swatch values.
165	 *
166	 * `urlBuilder` and `colourAttrId` are injected so this module stays dependency-free and
167	 * testable without a router context — the same pattern `selectPdpProductInfo` uses for
168	 * `formatPrice`.
169	 *
170	 * @param rawSwatches - The raw `c_relatedSwatches` array, pre-filtered by the SCAPI hook.
171	 * @param urlBuilder - Returns the base product URL for a given ID (e.g. `productUrlBuilder`).
172	 * @param colourAttrId - URL query-param key for the colour value (e.g. `'color'`).
173	 * @returns ZimmColourSwatchGroup-compatible swatch values with `forceReload: true`.
174	 */
175	export const buildRelatedSwatches = (
176	  rawSwatches: RelatedSwatch[],
177	  urlBuilder: (params: { id: string }) => string,
178	  colourAttrId: string,
179	) =>
180	  rawSwatches.map((item) => ({
181	    value: item.masterProductID,
182	    name: item.displayName,
183	    imageUrl: item.swatchImageURL,
184	    href: `${urlBuilder({ id: item.masterProductID })}?${colourAttrId}=${encodeURIComponent(item.colourValue)}`,
185	    orderable: true as const,
186	    forceReload: true as const,
187	  }));
188

